/* ================================================================ */
/* VOLCANIC tileset                                                 */
/* ================================================================ */
enum {
  MT_VO_ASH,  /* soft volcanic ash (+ ASH2, ASH3 variants) */
  MT_VO_ASH2,
  MT_VO_ASH3,
  MT_VO_BASALT,  /* columnar basalt seen from above: hexagonal column tops (+ BASALT2) */
  MT_VO_BASALT2,
  MT_VO_SETTS,  /* dressed hexagonal basalt street paving (Cindermoor) */
  MT_VO_SULFUR,  /* ash crusted with yellow sulfur */
  MT_VO_EMBERBRUSH,  /* scorched brush with glowing seed heads; wild kin roam here (top = front blades) */
  MT_VO_CLIFF,  /* basalt column cliff with an ash lip (solid); tiles horizontally */
  MT_VO_CLIFF_FACE,  /* plain basalt columns; stack under CLIFF (solid) */
  MT_VO_LEDGE,  /* one-way ash ledge: walk DOWN onto it to hop (+ _L/_R ends) */
  MT_VO_LEDGE_L,
  MT_VO_LEDGE_R,
  MT_VO_RAIL_H,  /* mine-cart rails on cinder ballast, running east-west (walkable) */
  MT_VO_RAIL_V,  /* mine-cart rails running north-south (walkable) */
  MT_VO_CRAG_TOP,  /* 16x32 basalt spire (map borders): TOP above BOTTOM; overlay */
  MT_VO_CRAG_BOTTOM,
  MT_VO_DEADTREE_TOP,  /* 16x32 charred tree: TOP above BOTTOM; overlay */
  MT_VO_DEADTREE_BOTTOM,
  MT_VO_CAVE_FLOOR,  /* Ember Tunnel grit floor (+ CAVE_FLOOR2) */
  MT_VO_CAVE_FLOOR2,
  MT_VO_CAVE_WALL,  /* rock mass above a cave wall (solid) */
  MT_VO_CAVE_FACE,  /* cave wall face down to the floor, lava-lit foot (solid) */
  MT_VO_CAVE_EXIT,  /* exit mat of a cave (walk DOWN to leave) */
  MT_VO_EMBERMOSS,  /* glowing ember moss on the cave floor; wild kin roam here */
  MT_VO_HALL_FLOOR,  /* riveted iron deck plates (Anvil Hall) (+ HALL_VENT grate) */
  MT_VO_HALL_VENT,
  MT_VO_HALL_WALL_TOP,  /* upper brick hall wall (solid) */
  MT_VO_HALL_WALL,  /* lower hall wall: brick over an iron rail (solid) */
  MT_VO_HALL_MAT,  /* Anvil Hall exit mat */
  MT_VO_LAVA,  /* animated lava (solid): LAVA_N/S/W/E edges, _NW/_NE/_SW/_SE outer corners, _INW/_INE/_ISW/_ISE inner corners, _H/_V one-cell streams, _POOL a single cell */
  MT_VO_LAVA_N,
  MT_VO_LAVA_S,
  MT_VO_LAVA_W,
  MT_VO_LAVA_E,
  MT_VO_LAVA_NW,
  MT_VO_LAVA_NE,
  MT_VO_LAVA_SW,
  MT_VO_LAVA_SE,
  MT_VO_LAVA_INW,
  MT_VO_LAVA_INE,
  MT_VO_LAVA_ISW,
  MT_VO_LAVA_ISE,
  MT_VO_LAVA_H,
  MT_VO_LAVA_V,
  MT_VO_LAVA_POOL,
  MT_VO_ASH_P,
  MT_VO_ASH_O,
  MT_VO_EMBERBRUSH_B,
  MT_VO_EMBERBRUSH_C,
  MT_VO_EMBERMOSS_B,
  MT_VO_EMBERMOSS_C,
  MT_VO_TERRAIN_COUNT
};
