/* ================================================================ */
/* DUSK tileset                                                     */
/* ================================================================ */
enum {
  MT_DU_ASH,  /* drifted ash (+ ASH2 cinders, ASH3 a bone chip and an ember) */
  MT_DU_ASH2,
  MT_DU_ASH3,
  MT_DU_ASH_GRASS,  /* dead grass on ash; wild kin roam; top layer = front blades */
  MT_DU_SCORCH,  /* burnt earth with cracks */
  MT_DU_EMBERS,  /* smouldering cracks, animated (walkable) */
  MT_DU_COBBLE,  /* old cobbles of the ash road and the Duskmere square */
  MT_DU_GRAVE_SOIL,  /* dark loam with fallen leaves (Gravewood floor, + variant) */
  MT_DU_GRAVE_SOIL2,
  MT_DU_GRAVE_BRUSH,  /* dead bracken; wild kin roam; top layer = front fronds */
  MT_DU_MUD,  /* peat mud (+ MUD2 with a puddle and foxfire specks) */
  MT_DU_MUD2,
  MT_DU_MOSS,  /* moss carpet on the mud */
  MT_DU_MIRE_REEDS,  /* reeds in the mud; wild kin roam; top layer = front stalks */
  MT_DU_DECK,  /* weathered planks (Duskmere platforms) */
  MT_DU_GNARL_TOP,  /* 16x32 dead oak: TOP above BOTTOM (overlay) */
  MT_DU_GNARL_BOTTOM,
  MT_DU_SNAG_TOP,  /* 16x32 charred pine with ember cracks (overlay; forest walls) */
  MT_DU_SNAG_BOTTOM,
  MT_DU_CYPRESS_TOP,  /* 16x32 swamp cypress with hanging moss (overlay) */
  MT_DU_CYPRESS_BOTTOM,
  MT_DU_LEDGE,  /* one-way ash ledge: walk DOWN onto it to hop over */
  MT_DU_LEDGE_L,
  MT_DU_LEDGE_R,
  MT_DU_CRAG,  /* rock wall with an ash lip (solid); CRAG_FACE stacks below */
  MT_DU_CRAG_FACE,
  MT_DU_ASH4,
  MT_DU_ASH_GRASS_B,
  MT_DU_ASH_GRASS_C,
  MT_DU_GRAVE_BRUSH_B,
  MT_DU_GRAVE_BRUSH_C,
  MT_DU_MIRE_REEDS_B,
  MT_DU_MIRE_REEDS_C,
  MT_DU_TERRAIN_COUNT
};
